// Branded ids and the injected id generator (BUILD_PLAN module 1, DATA_MODEL §0 "Ids").
//
// Every id is a UUIDv7 generated by core (the DB has no defaults). Generation is pure given its
// inputs: the clock and the random source are injected, so `packages/core` never touches
// `crypto` or the wall clock. The API wires `uuidv7Generator(clock, crypto.getRandomValues-based
// bytes)`; tests use `sequentialIds()`.
import { type Clock, type Instant, instant } from './time.js';

export type Brand<T, B extends string> = T & { readonly __brand: B };

