// ---- generator --------------------------------------------------------------------------------

export interface IdGenerator {
  /** A fresh UUIDv7 branded as `T`, e.g. `ids.next<'ContactId'>()`. */
  next<T extends string>(): Brand<string, T>;
}

/** Fills `n` cryptographically random bytes (injected; e.g. `crypto.getRandomValues` in the API). */
export type RandomBytes = (n: number) => Uint8Array;

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const UUID_V7_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const RAND_BITS = 74n; // 12 bits rand_a + 62 bits rand_b
const RAND_MAX = (1n << RAND_BITS) - 1n;
const MAX_TS = 2 ** 48 - 1;

function formatV7(ms: number, rand: bigint): string {
  const randA = Number(rand >> 62n); // 12 bits
  const randB = rand & ((1n << 62n) - 1n); // 62 bits
  const hi = ms.toString(16).padStart(12, '0');
  const verA = (0x7000 | randA).toString(16).padStart(4, '0');
  const varB = ((0b10n << 62n) | randB).toString(16).padStart(16, '0');
  return `${hi.slice(0, 8)}-${hi.slice(8, 12)}-${verA}-${varB.slice(0, 4)}-${varB.slice(4)}`;
}

function bytesToBigInt(bytes: Uint8Array): bigint {
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v;
}

/**
 * RFC 9562 UUIDv7 generator: 48-bit unix ms, version 7, variant 10, 74 random bits.
 *
 * Ids from one generator are strictly increasing (byte order = string order), even when several
 * are minted in the same millisecond or the clock steps backwards: in that case the previous
 * timestamp is kept and the random field is incremented by a random 1..2^32 step (RFC 9562 §6.2,
 * method 2). On the (astronomically unlikely) overflow of the random field the timestamp advances
 * by 1 ms.
 */
export function uuidv7Generator(clock: Clock, randomBytes: RandomBytes): IdGenerator {
  let lastMs = -1;
  let lastRand = 0n;
  const fresh = (): bigint => bytesToBigInt(randomBytes(10)) & RAND_MAX; // 80 bits → 74
  const step = (): bigint => (bytesToBigInt(randomBytes(4)) & 0xffff_ffffn) + 1n;
  return {
    next<T extends string>(): Brand<string, T> {
      const nowMs = clock.now();
      if (nowMs < 0 || nowMs > MAX_TS) throw new RangeError('uuidv7: clock outside the 48-bit millisecond range');
      let ms: number;
      let rand: bigint;
      if (nowMs > lastMs) {
        ms = nowMs;
        rand = fresh();
      } else {
        ms = lastMs;
        rand = lastRand + step();
        if (rand > RAND_MAX) {
          ms = lastMs + 1;
          rand = fresh();
        }
      }
      lastMs = ms;
      lastRand = rand;
      return formatV7(ms, rand) as Brand<string, T>;
    },
  };
}

/**
 * Deterministic ids for tests: valid UUIDv7-shaped strings (insertable into `uuid` columns) that
 * sort in issue order. `prefix` (0..2^32-1) occupies the first 8 hex digits so that several
 * generators in one database never collide.
 *
 *   sequentialIds().next() === '00000000-0000-7000-8000-000000000001'
 */
export function sequentialIds(opts: { start?: number; prefix?: number } = {}): IdGenerator & { readonly issued: number } {
  const prefix = opts.prefix ?? 0;
  let n = opts.start ?? 1;
  if (!Number.isSafeInteger(prefix) || prefix < 0 || prefix > 0xffff_ffff) throw new RangeError('sequentialIds: prefix must be 0..2^32-1');
  if (!Number.isSafeInteger(n) || n < 0) throw new RangeError('sequentialIds: start must be a non-negative integer');
  let issued = 0;
  return {
    next<T extends string>(): Brand<string, T> {
      if (n > 0xffff_ffff_ffff) throw new RangeError('sequentialIds: exhausted');
      const id = `${prefix.toString(16).padStart(8, '0')}-0000-7000-8000-${n.toString(16).padStart(12, '0')}`;
      n += 1;
      issued += 1;
      return id as Brand<string, T>;
    },
    get issued() {
      return issued;
    },
  };
}

export function isUuid(s: string): boolean {
  return UUID_RE.test(s);
}

export function isUuidV7(s: string): boolean {
  return UUID_V7_RE.test(s);
}

/** Validates and canonicalises (lower-cases) a uuid from untrusted input. Null if malformed. */
export function parseId<T extends string>(s: string): Brand<string, T> | null {
  return UUID_RE.test(s) ? (s.toLowerCase() as Brand<string, T>) : null;
}

/** The embedded millisecond timestamp of a UUIDv7, or null for other uuids. */
export function uuidv7Time(id: string): Instant | null {
  if (!UUID_V7_RE.test(id)) return null;
  return instant(parseInt(id.slice(0, 8) + id.slice(9, 13), 16));
}
